#!/usr/bin/env python3
# ruff: noqa: T201, DTZ007
"""Keeps the Alembic history of the feinarbyte build safe to deploy.

Upstream keeps a strictly linear migration history. Our feature branches add
migrations of their own, so after merging upstream the history regularly ends
up with two heads, and Mealie refuses to start in that state.

This script is run by sync.sh after every merge and does three things:

1. verify: every migration that was part of a published build must still exist
   with the same parents (see migrations.lock). A database that already applied
   a migration would silently skip any migration that is later slotted in
   *before* it, so published history is append-only.
2. merge: if there is more than one head, write an empty merge migration.
3. record: rewrite migrations.lock with the resulting history.

It only reads the migration files as text (no imports, no parsing), so it needs nothing but
the Python standard library.
"""

from __future__ import annotations

import datetime as dt
import hashlib
import re
import sys
from pathlib import Path

REPO_ROOT = Path(__file__).resolve().parents[2]
VERSIONS_DIR = REPO_ROOT / "mealie" / "alembic" / "versions"
LOCK_FILE = Path(__file__).resolve().parent / "migrations.lock"

FILE_TIMESTAMP_FORMAT = "%Y-%m-%d-%H.%M.%S"
FILE_TIMESTAMP_RE = re.compile(r"^(\d{4}-\d{2}-\d{2}-\d{2}\.\d{2}\.\d{2})_")

MERGE_TEMPLATE = '''"""{message}

Revision ID: {revision}
Revises: {revises}
Create Date: {create_date}

Generated by .github/fork/migrations.py. It joins the upstream migration
history with the migrations of the feinarbyte feature branches and must never
be edited or removed once it was part of a published build.
"""

# revision identifiers, used by Alembic.
revision: str = "{revision}"
down_revision: str | tuple[str, ...] | None = ({down_tuple})
branch_labels: str | tuple[str, ...] | None = None
depends_on: str | tuple[str, ...] | None = None


def upgrade():
    pass


def downgrade():
    pass
'''


class MigrationError(Exception):
    pass


def _read_identifier(name: str, source: str, path: Path) -> tuple[str, ...]:
    match = re.search(rf"^{name}\b[^=\n]*=\s*(\(.*?\)|\[.*?\]|None\b|\"[^\"\n]*\"|'[^'\n]*')", source, re.M | re.S)
    if match is None:
        raise MigrationError(f"{path.name}: could not read {name}")
    return tuple(a or b for a, b in re.findall(r"\"([^\"\n]+)\"|'([^'\n]+)'", match.group(1)))


def read_migration(path: Path) -> tuple[str, tuple[str, ...]]:
    """Returns (revision, parents) of a migration file.

    Parsed with regular expressions rather than `ast`: the migrations may use syntax
    that is newer than the Python that happens to run this script.
    """
    source = path.read_text(encoding="utf-8")
    revision = _read_identifier("revision", source, path)
    if len(revision) != 1:
        raise MigrationError(f"{path.name}: could not read revision")
    return revision[0], tuple(sorted(_read_identifier("down_revision", source, path)))


def read_graph() -> tuple[dict[str, tuple[str, ...]], dict[str, Path]]:
    graph: dict[str, tuple[str, ...]] = {}
    files: dict[str, Path] = {}
    for path in sorted(VERSIONS_DIR.glob("*.py")):
        revision, parents = read_migration(path)
        if revision in graph:
            raise MigrationError(
                f"revision {revision} is defined twice:\n"
                f"  {files[revision].name}\n  {path.name}\n"
                "This usually means upstream merged one of our features with a re-dated "
                "migration file. Keep the file that is listed in migrations.lock and delete "
                "the other one (see .github/fork/README.md)."
            )
        graph[revision] = parents
        files[revision] = path

    for revision, parents in graph.items():
        for parent in parents:
            if parent not in graph:
                raise MigrationError(f"{files[revision].name}: unknown down_revision {parent}")
    return graph, files


def get_heads(graph: dict[str, tuple[str, ...]]) -> list[str]:
    parents = {p for ps in graph.values() for p in ps}
    return sorted(r for r in graph if r not in parents)


def read_lock() -> dict[str, tuple[str, ...]]:
    locked: dict[str, tuple[str, ...]] = {}
    if not LOCK_FILE.exists():
        return locked
    for line in LOCK_FILE.read_text(encoding="utf-8").splitlines():
        line = line.split("#", 1)[0].strip()
        if not line:
            continue
        revision, _, parents = line.partition(":")
        locked[revision.strip()] = tuple(sorted(parents.split()))
    return locked


def verify(graph: dict[str, tuple[str, ...]], files: dict[str, Path]) -> None:
    problems: list[str] = []
    for revision, parents in read_lock().items():
        if revision not in graph:
            problems.append(f"  {revision}: was published, but the migration no longer exists")
        elif graph[revision] != parents:
            problems.append(
                f"  {revision} ({files[revision].name}): parents changed from "
                f"[{', '.join(parents) or 'none'}] to [{', '.join(graph[revision]) or 'none'}]"
            )
    if problems:
        raise MigrationError(
            "Migrations that are already part of a published build were changed:\n"
            + "\n".join(problems)
            + "\n\nA deployed database would skip or fail on these. Restore the files as they are on "
            "feinarbyte/main; the differing histories are joined by a merge migration instead. "
            "See .github/fork/README.md."
        )


def merge_heads(graph: dict[str, tuple[str, ...]], files: dict[str, Path]) -> Path | None:
    heads = get_heads(graph)
    if len(heads) < 2:
        return None

    # Derived from the heads, so that re-running the sync produces the same migration.
    revision = hashlib.sha1("+".join(heads).encode()).hexdigest()[:12]

    # tests/utils/alembic_reader.py treats the last file by name as the head,
    # so the merge has to sort after every existing migration.
    now = dt.datetime.now(dt.UTC).replace(microsecond=0, tzinfo=None)
    for path in files.values():
        if match := FILE_TIMESTAMP_RE.match(path.name):
            existing = dt.datetime.strptime(match.group(1), FILE_TIMESTAMP_FORMAT)
            now = max(now, existing + dt.timedelta(seconds=1))

    path = VERSIONS_DIR / f"{now.strftime(FILE_TIMESTAMP_FORMAT)}_{revision}_feinarbyte_merge_heads.py"
    path.write_text(
        MERGE_TEMPLATE.format(
            message="feinarbyte: merge heads " + ", ".join(heads),
            revision=revision,
            revises=", ".join(heads),
            create_date=now.isoformat(sep=" "),
            down_tuple=", ".join(f'"{h}"' for h in heads),
        ),
        encoding="utf-8",
    )
    return path


def record(graph: dict[str, tuple[str, ...]]) -> None:
    lines = [
        "# Alembic history of the feinarbyte build: `revision: parents`.",
        "# Maintained by .github/fork/migrations.py; do not edit by hand unless",
        "# .github/fork/README.md tells you to.",
    ]
    lines += [f"{revision}: {' '.join(parents)}".rstrip() for revision, parents in sorted(graph.items())]
    LOCK_FILE.write_text("\n".join(lines) + "\n", encoding="utf-8")


def main() -> int:
    command = sys.argv[1] if len(sys.argv) > 1 else "sync"
    if command not in ("sync", "check"):
        print(f"usage: {sys.argv[0]} [sync|check]", file=sys.stderr)
        return 2

    try:
        graph, files = read_graph()
        verify(graph, files)

        if command == "check":
            heads = get_heads(graph)
            if len(heads) != 1:
                raise MigrationError(f"expected exactly one head, found: {', '.join(heads)}")
            print(f"ok: {len(graph)} migrations, head {heads[0]}")
            return 0

        if created := merge_heads(graph, files):
            print(f"created merge migration {created.name}")
            graph, files = read_graph()

        heads = get_heads(graph)
        if len(heads) != 1:
            raise MigrationError(f"expected exactly one head, found: {', '.join(heads)}")
        record(graph)
        print(f"ok: {len(graph)} migrations, head {heads[0]}")
    except MigrationError as e:
        print(f"::error::Alembic history check failed\n{e}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
